sunmi=root/'app/src/main/java/com/mahmoud/meposcashier/SunmiPrinter.java'
sunmi.write_text('''package com.mahmoud.meposcashier;\n\nimport android.content.Context;\nimport android.os.RemoteException;\nimport com.sunmi.peripheral.printer.InnerPrinterCallback;\nimport com.sunmi.peripheral.printer.InnerPrinterException;\nimport com.sunmi.peripheral.printer.InnerPrinterManager;\nimport com.sunmi.peripheral.printer.SunmiPrinterService;\n\npublic final class SunmiPrinter {\n    private final Context context;\n    private volatile SunmiPrinterService service;\n    private final InnerPrinterCallback callback=new InnerPrinterCallback(){\n        @Override protected void onConnected(SunmiPrinterService s){ service=s; }\n        @Override protected void onDisconnected(){ service=null; }\n    };\n    public SunmiPrinter(Context c){ context=c.getApplicationContext(); }\n    public void bind(){ try{ InnerPrinterManager.getInstance().bindService(context,callback); }catch(InnerPrinterException ignored){ service=null; } }\n    public boolean print(String text){\n        SunmiPrinterService s=service; if(s==null)return false;\n        try{\n            s.printerInit(null);\n            s.setAlignment(1,null);\n            s.printText(text+"\\n",null);\n            s.lineWrap(4,null);\n            try{s.cutPaper(null);}catch(Exception ignored){}\n            return true;\n        }catch(RemoteException e){ service=null; return false; }\n    }\n    public void close(){ try{ InnerPrinterManager.getInstance().unBindService(context,callback); }catch(Exception ignored){} service=null; }\n}\n''',encoding='utf-8')

